INSERT INTO competition (id, title_cn, title_en, description, category, level, participant_type, instructor_name, school, target_audience, poster, status, deadline, organizer, rules, awards) VALUES
(1, '全国大学生数学建模竞赛', 'National Math Modeling Contest', '中国规模最大的数学建模赛事之一，培养大学生运用数学方法和计算机工具解决实际问题的能力。', '国内竞赛', '国家级', '团队', '刘教授', '凡尔赛美术学院', '全国高校在校本科生', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=400&q=80', 'open', '2026-09-15', '中国工业与应用数学学会', '1. 每组最多3人，需在规定时间内完成题目并提交论文。\n2. 竞赛期间可使用各类图书资料、计算机和软件。\n3. 不得与组外人员讨论，不得抄袭他人成果。\n4. 论文需符合格式要求，按时通过官方系统提交。', '一等奖：前1%，获奖证书 + 奖金5000元\n二等奖：前5%，获奖证书 + 奖金2000元\n三等奖：前15%，获奖证书\n优秀奖：若干，获奖证书'),
(2, '全国英语写作大赛', 'National English Writing Contest', '全国性英语写作赛事，提升学术英语写作能力，培养批判性思维与表达能力。', '国内写作', '国家级', '个人', '陈教授', '北京外国语大学', '全国高校在校生', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=400&q=80', 'open', '2026-10-01', '北京外国语大学', '1. 参赛作品须为原创，不得抄袭。\n2. 文章字数在1500-3000词之间。\n3. 主题自选，需符合学术规范。\n4. 提交截止日期前通过官网系统上传。', '一等奖：1名，奖金3000元 + 证书\n二等奖：3名，奖金1000元 + 证书\n三等奖：10名，证书\n优秀奖：若干，证书'),
(3, '国际生物奥林匹克竞赛', 'International Biology Olympiad', '全球顶级生物学赛事，选拔和培养生物学科顶尖人才，与各国优秀学生同台竞技。', '国际竞赛', '国际级', '团队', '周教授', '北京大学', '全国中学生', 'https://images.unsplash.com/photo-1530210124550-912a7fe4def1?w=400&q=80', 'open', '2026-11-30', '国际生物奥林匹克组委会', '1. 参赛者须为中学生，年龄不超过19岁。\n2. 比赛分为理论和实验两部分。\n3. 各国限派4名代表参赛。\n4. 比赛语言为英语。', '金牌：前10%\n银牌：前25%\n铜牌：前50%\n参赛证书：所有参赛者'),
(4, 'ACM程序设计大赛', 'ACM Programming Contest', '全球最具影响力的大学生程序设计竞赛，培养算法设计、编程实现与团队协作能力。', '国际竞赛', '国际级', '团队', '王教授', '清华大学', '全国高校在校本科生', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?w=400&q=80', 'open', '2026-08-20', 'ACM国际计算机协会', '1. 每队3人，使用1台电脑。\n2. 比赛时长5小时，共8-12道题。\n3. 编程语言限C/C++/Java/Python。\n4. 按解题数量和罚时排名。', '冠军：奖杯 + 奖金10000元\n亚军：奖金5000元\n季军：奖金3000元\n优胜奖：前20名队伍，证书');
INSERT INTO research_tour (id, title_cn, title_en, description, country, season, instructor_name, instructor_title, school, target_audience, poster, status, location, duration, max_enrollment, schedule, notice) VALUES
(1, '暑期科研集训营 · 清华大学', 'Summer Research Camp', '由清华大学主办的沉浸式科研体验项目，为全国优秀大学生提供近距离接触前沿科研的机会，培养学术兴趣与研究能力。', '中国', '暑假', '张教授', '清华大学', '清华大学', '高中生 / 本科生', 'https://images.unsplash.com/photo-1562774053-701939374585?w=400&q=80', 'open', '清华大学校内', '2周', 30, '第一周：开营仪式 + 实验室参观 + 导师讲座\n第二周：分组研究 + 成果汇报 + 结营仪式\n每日安排：上午课程 + 下午实践 + 晚间研讨', '报名时间：2026年6月1日 — 2026年7月10日\n申请材料：个人简历 + 成绩单 + 推荐信（可选）\n名额有限，报满即止'),
(2, '海外名校研学 · 剑桥大学', 'Cambridge Study Tour', '走进剑桥大学，体验世界顶尖学府的学术氛围，与剑桥教授面对面交流，拓展国际学术视野。', '英国', '暑假', '李教授', '剑桥大学', '剑桥大学', '本科生 / 研究生', 'https://images.unsplash.com/photo-1541339907198-e08756dedf3f?w=400&q=80', 'open', '英国剑桥大学', '3周', 25, '第一周：校园导览 + 学术讲座 + 文化体验\n第二周：专业课程 + 实验室参访 + 小组研讨\n第三周：研究项目 + 学术报告 + 结业典礼', '报名时间：2026年4月1日 — 2026年6月15日\n申请材料：个人简历 + 在校成绩单 + 英语水平证明\n签证自理，学校提供邀请函'),
(3, '学术写作工作坊 · 北京大学', 'Academic Writing Workshop', '由北京大学主办的学术写作强化项目，系统学习学术论文写作方法、文献综述技巧与发表策略。', '中国', '秋季', '王教授', '北京大学', '北京大学', '本科生', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?w=400&q=80', 'open', '北京大学校内', '1周', 40, 'Day1：学术写作基础与规范\nDay2：文献检索与综述方法\nDay3：论文结构与论证逻辑\nDay4：数据分析与可视化\nDay5：修改润色与投稿策略\nDay6：一对一指导\nDay7：成果展示与结业', '报名时间：2026年8月1日 — 2026年9月20日\n申请材料：个人简历 + 写作样本（可选）\n适合有论文写作需求的学生'),
(4, '人工智能研学营 · 斯坦福大学', 'AI Research Camp', '深度体验斯坦福大学人工智能研究方向，参与AI前沿课题，动手训练自己的机器学习模型。', '美国', '寒假', '陈教授', '斯坦福大学', '斯坦福大学', '本科生 / 研究生', 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=400&q=80', 'open', '美国斯坦福大学', '2周', 20, '第一周：AI导论 + 机器学习基础 + Python实战\n第二周：深度学习 + 计算机视觉/NLP + 项目展示\n每周安排：上午讲座 + 下午实验室 + 晚间团队项目', '报名时间：2026年10月1日 — 2026年12月15日\n申请材料：个人简历 + 编程基础证明 + 英语水平证明\n需自备笔记本电脑，签证自理');
